    d: "M0.809327 17.2572L16.334 14.4126C16.334 14.4126 15.0643 15.5534 15.1201 18.0228C15.1797 20.6545 16.334 21.6331 16.334 21.6331H0.925242C0.925242 21.6331 0.0136566 21.0675 0.000145916 19.3631C-0.0125644 17.7624 0.809327 17.2572 0.809327 17.2572Z",
