// In viewBox units.
const SWEEP_BAND = 56;
const MARK_WIDTH = 20.01;

export default function GrowthBookLogo({
  showWordmark,
  className,
  markClassName,
  wordmarkClassName,
  sweepClassName,
}: {
  showWordmark: boolean;
  className?: string;
  markClassName?: string;
  wordmarkClassName?: string;
  /** The caller's CSS animates this class, translating by --sweep-distance. */
  sweepClassName?: string;
}) {
  // url() references break on useId's colons.
  const id = useId().replace(/:/g, "");
  const gradientId = `gb-logo-sweep-${id}`;
  const clipId = `gb-logo-clip-${id}`;
  const wordmarkTransform = `translate(${WORDMARK_SHIFT} ${-WORDMARK_RISE})`;
  return (
    <svg
      width={WIDTH * LOGO_SCALE}
      height={HEIGHT * LOGO_SCALE}
      viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-hidden="true"
      focusable="false"
    >
      {MARK.map(({ d, fill }) => (
        <path
          key={fill}
          fillRule="evenodd"
          clipRule="evenodd"
          d={d}
          fill={fill}
          className={markClassName}
        />
      ))}
      {showWordmark ? (
        <path
          fillRule="evenodd"
          clipRule="evenodd"
          d={WORDMARK}
          transform={wordmarkTransform}
          className={wordmarkClassName}
        />
      ) : null}
      {sweepClassName ? (
        <>
          <defs>
            <linearGradient id={gradientId} x1="0" x2="1" y1="0" y2="0">
              <stop offset="0" stopColor="#029DD1" stopOpacity="0" />
              <stop offset="0.3" stopColor="#029DD1" />
              <stop offset="0.5" stopColor="#0047BD" />
              <stop offset="0.7" stopColor="#4817A1" />
              <stop offset="1" stopColor="#4817A1" stopOpacity="0" />
            </linearGradient>
            <clipPath id={clipId}>
              {MARK.map(({ d, fill }) => (
                <path key={fill} clipRule="evenodd" d={d} />
              ))}
              {showWordmark ? (
                <path
                  clipRule="evenodd"
                  d={WORDMARK}
                  transform={wordmarkTransform}
                />
              ) : null}
            </clipPath>
          </defs>
          <g clipPath={`url(#${clipId})`}>
            <rect
              x={-SWEEP_BAND}
              y="0"
              width={SWEEP_BAND}
              height={HEIGHT}
              fill={`url(#${gradientId})`}
              className={sweepClassName}
              style={
                {
                  "--sweep-distance": `${
                    (showWordmark ? WIDTH : MARK_WIDTH) + SWEEP_BAND
                  }px`,
                } as CSSProperties
              }
            />
          </g>
        </>
      ) : null}
    </svg>
  );
}
